// 3 days/week, ~60 min sessions, hard intensity. Equipment: Barbell, rack & bench, Pull-up bar.
# Week 1
// Estimated ~55 min
## Full Body A
// Brace, sit between your hips, knees track over toes.
Squat, Barbell / 3x5, 1x5+ / 20kg / 180s / progress: lp(2.5kg, 1, 0, 10%, 2, 0)
// Shoulder blades pinched, bar to lower chest, feet planted.
Bench Press, Barbell / 3x5, 1x5+ / 20kg / 180s / progress: lp(2.5kg, 1, 0, 10%, 2, 0)
// Hinge to ~45°, pull the bar to your belly button.
Bent Over Row, Barbell / 3x5, 1x5+ / 20kg / 180s / progress: lp(2.5kg, 1, 0, 10%, 2, 0)
// Low back pressed into the floor, extend opposite arm and leg.
Dead Bug, Bodyweight / 3x8, 1x8+ / 0kg / 90s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}

// Estimated ~54 min
## Full Body B
// Soft knees, push hips back until hamstrings stretch.
Romanian Deadlift, Barbell / 3x5, 1x5+ / 30kg / 180s / progress: lp(2.5kg, 1, 0, 10%, 2, 0)
// Squeeze glutes, press the bar up and move your head through.
Overhead Press, Barbell / 3x5, 1x5+ / 20kg / 180s / progress: lp(2.5kg, 1, 0, 10%, 2, 0)
// Palms facing you, pull chin over the bar. Do negatives if needed.
Chin Up, Bodyweight / 3x8, 1x8+ / 0kg / 90s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Bar on your back, controlled step forward.
Lunge, Barbell / 3x8 / 20kg / 90s / warmup: none / progress: dp(2.5kg, 8, 12)
// Hands on the bench edge, lower until elbows reach 90°.
Bench Dip, Bodyweight / 3x8, 1x8+ / 0kg / 90s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}

// Estimated ~52 min
## Full Body C
// Brace, sit between your hips, knees track over toes.
Squat, Barbell / 3x5, 1x5+ / 20kg / 180s
// Body in one straight line, chest to just above the floor.
Push Up, Bodyweight / 3x8, 1x8+ / 0kg / 90s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Bar set low in the rack, body straight, pull chest to bar.
Inverted Row, Bodyweight / 3x8, 1x8+ / 0kg / 90s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Upper back on the bench, chin tucked, squeeze at the top.
Hip Thrust, Barbell / 3x8 / 30kg / 90s / warmup: none / progress: dp(2.5kg, 8, 12)
// Hang still, bring knees up without swinging.
Hanging Knee Raise, Bodyweight / 3x8, 1x8+ / 0kg / 90s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Shoulder-width grip, elbows by your sides.
Bicep Curl, Barbell / 3x8 / 15kg / 90s / warmup: none / progress: dp(2.5kg, 8, 12)
